-- Structured alert and advisory ingestion (POST /v1/ingest). Items are
-- tenant-private and the id is derived from tenant, source and external ID, so
-- a repeat submission updates the stored row instead of adding one.
CREATE TABLE ingest_items (id TEXT NOT NULL, tenant_id TEXT NOT NULL REFERENCES tenants(id), type TEXT NOT NULL CHECK(type IN ('alert','advisory')), format TEXT NOT NULL CHECK(format IN ('native','stix','csaf','osv')), source_key TEXT NOT NULL, external_id TEXT NOT NULL, severity TEXT NOT NULL CHECK(severity IN ('info','low','medium','high','critical')), tlp TEXT NOT NULL CHECK(tlp IN ('clear','green','amber','amber+strict','red')), title TEXT NOT NULL, content_hash TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), normalisation TEXT NOT NULL CHECK(json_valid(normalisation)), raw TEXT, raw_key TEXT, revision INTEGER NOT NULL DEFAULT 1, source_updated_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, created_by TEXT NOT NULL, updated_by TEXT NOT NULL, last_ingest_id TEXT NOT NULL, PRIMARY KEY(tenant_id,id), UNIQUE(tenant_id,source_key,external_id));
CREATE INDEX ingest_items_recent ON ingest_items(tenant_id,updated_at DESC,id);
CREATE TABLE ingest_batches (id TEXT NOT NULL, tenant_id TEXT NOT NULL REFERENCES tenants(id), job_id TEXT NOT NULL, key_id TEXT NOT NULL, user_id TEXT NOT NULL, format TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('queued','complete')), received INTEGER NOT NULL, accepted INTEGER NOT NULL, rejected INTEGER NOT NULL, superseded INTEGER NOT NULL DEFAULT 0, created INTEGER NOT NULL DEFAULT 0, updated INTEGER NOT NULL DEFAULT 0, unchanged INTEGER NOT NULL DEFAULT 0, items TEXT NOT NULL CHECK(json_valid(items)), errors TEXT NOT NULL CHECK(json_valid(errors)), request_id TEXT NOT NULL, created_at TEXT NOT NULL, completed_at TEXT, PRIMARY KEY(tenant_id,id));
-- Idempotency-Key replay: the first response is returned for the same body.
CREATE TABLE ingest_requests (tenant_id TEXT NOT NULL REFERENCES tenants(id), request_key TEXT NOT NULL, body_hash TEXT NOT NULL, status INTEGER NOT NULL, response TEXT NOT NULL CHECK(json_valid(response)), created_at TEXT NOT NULL, PRIMARY KEY(tenant_id,request_key));
CREATE TABLE ingest_metrics (tenant_id TEXT NOT NULL REFERENCES tenants(id), day TEXT NOT NULL, received INTEGER NOT NULL DEFAULT 0, accepted INTEGER NOT NULL DEFAULT 0, rejected INTEGER NOT NULL DEFAULT 0, deduplicated INTEGER NOT NULL DEFAULT 0, created INTEGER NOT NULL DEFAULT 0, updated INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(tenant_id,day));
-- Optional per-key source restriction: a JSON array of source names.
ALTER TABLE api_keys ADD COLUMN ingest_sources TEXT CHECK(ingest_sources IS NULL OR json_valid(ingest_sources));
